from __future__ import annotations
from dataclasses import dataclass
from .rng import keyed_rng

# Python integers are arbitrary precision. This constant is NEVER enumerated or
# converted to float; layers are generated by direct keyed sampling.
MAX_LAYER = 10**100

@dataclass(frozen=True)
class Civilization:
    i: int
    j: int
    layer: int
    hostile: bool
    defense: float
    identifier: str

class ProceduralWorld:
    def __init__(self, cfg: dict):
        self.cfg=cfg
        self.seed=int(cfg["simulation"]["seed"])
        self.na=int(cfg["world"]["na"])
        self.tolerance=float(cfg["world"]["hostility_tolerance"])

    def validate_layer(self, layer: int) -> int:
        layer=int(layer)
        if layer < 0 or layer > MAX_LAYER:
            raise ValueError("Layer outside [0, 10^100].")
        return layer

    def cell_center_xy(self, i: int, j: int) -> tuple[float,float]:
        # 1 unit = 1 km; center of each 1-km cell.
        return (float(i)+0.5, float(j)+0.5)

    def layer_difference(self, a: int, b: int) -> int:
        # Exact integer arithmetic; safe even for 10^100.
        return int(a)-int(b)

    def civilization(self, i: int, j: int, layer: int) -> Civilization:
        layer=self.validate_layer(layer)
        # Stable, independent cell-level procedural draw.
        r=keyed_rng(self.seed,"civilization",int(i),int(j),layer)
        hostile=self.is_hostile(i,j,layer)
        defense=float(r.uniform(0.85,1.15))
        ident=f"c-{i}-{j}-L{layer}"
        return Civilization(int(i),int(j),layer,hostile,defense,ident)

    def hostility_score(self, i: int, j: int, layer: int) -> float:
        # Bounded, deterministic pseudo-random scalar. No large-world traversal.
        r=keyed_rng(self.seed,"hostility-score",int(i),int(j),layer)
        return float(r.random())

    def is_hostile(self, i: int, j: int, layer: int) -> bool:
        # Hostility depends on normalized score and y-only matching.
        # The caller's target y is used by hostility_match().
        return self.hostility_score(i,j,layer) < 0.12

    def hostility_match(self, attacker_y: float, target_y: float) -> bool:
        # Normalize the y difference by world width; no modulo/folding.
        scale=max(1.0,float(self.na))
        normalized=abs(float(attacker_y)-float(target_y))/scale
        return normalized <= self.tolerance

    def sample_layer_near(self, origin: int, max_delta: int, rng) -> int:
        lo=max(0,int(origin)-int(max_delta))
        hi=min(MAX_LAYER,int(origin)+int(max_delta))
        # Offset is small; never sample/iterate over all layers.
        delta=int(rng.integers(-max_delta,max_delta+1))
        return min(MAX_LAYER,max(0,int(origin)+delta))
